do $carga$
declare
  m record;
  v_modelo uuid;
  v_versao uuid;
begin
  for m in
    select * from jsonb_to_recordset($modelos$[{"chave":"homologacao_divorcio_consensual","tipo":"personalizado","categoria":"Petição","nome":"Ação de Homologação de Divórcio Consensual","titulo":"Ação de Homologação de Divórcio Consensual","fonte":"Ação de Homologação de Divórcio Consensual.docx","definicao":{"formato":1,"folha_origem":true,"corpo":[{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Ao Juízo "},{"tipo":"campo","chave":"oficial.juizo_docx"},{"tipo":"texto","valor":"|PR,"}],"classe":"doc-alinhar-esquerda"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Autos a serem distribuídas,"}],"classe":"doc-alinhar-justificar"},{"tipo":"elemento","tag":"h2","itens":[{"tipo":"campo","chave":"manual.assunto"},{"tipo":"texto","valor":","}],"classe":"doc-alinhar-esquerda doc-titulo"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"elemento","tag":"br","itens":[]}],"classe":"doc-alinhar-justificar"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"URGÊNCIA – "},{"tipo":"campo","chave":"manual.urgencia_detalhe"}],"classe":"doc-alinhar-justificar","modelo_condicao":"m_nota_5:Sim"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Prioridade +60, de acordo com o art. 71 da Lei 10.741/2003."}],"classe":"doc-alinhar-justificar","modelo_condicao":"m_nota_6:Sim"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Sigiloso, conforme art. 189, "},{"tipo":"campo","chave":"manual.trecho_7_1_1"},{"tipo":"texto","valor":", da Lei 13.105/2015."}],"classe":"doc-alinhar-justificar","modelo_condicao":"m_nota_7:Sim"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Gratuidade da justiça deferida em mov. "},{"tipo":"campo","chave":"manual.mov_gratuidade"},{"tipo":"texto","valor":"."}],"classe":"doc-alinhar-justificar","modelo_condicao":"m_nota_8:Sim"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Há interesse na audiência de conciliação/mediação."}],"classe":"doc-alinhar-justificar","modelo_condicao":"m_nota_9:Sim"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"elemento","tag":"br","itens":[]}],"classe":"doc-alinhar-justificar"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"elemento","tag":"span","itens":[{"tipo":"texto","valor":"Ementa. Descrição. Fatos e direitos. Resumão. Leitura dinâmica e rápida. Facilidade para o leitor. Detalhar em peças principais – inicial, contestação, réplica, razões finais, recursos e contrarrazões."}],"modelo_exemplo":"manual.ementa"}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"campo","chave":"cliente.nome"},{"tipo":"texto","valor":", "},{"tipo":"campo","chave":"cliente.nacionalidade"},{"tipo":"texto","valor":", "},{"tipo":"campo","chave":"cliente.estado_civil"},{"tipo":"texto","valor":", "},{"tipo":"campo","chave":"cliente.profissao"},{"tipo":"texto","valor":", "},{"tipo":"campo","chave":"cliente.inscrito"},{"tipo":"texto","valor":" no CPF de n.º "},{"tipo":"campo","chave":"cliente.cpf"},{"tipo":"texto","valor":", "},{"tipo":"campo","chave":"cliente.domiciliado"},{"tipo":"texto","valor":" na "},{"tipo":"campo","chave":"cliente.endereco"},{"tipo":"texto","valor":", Brasil; e, "},{"tipo":"campo","chave":"manual.conjuge_nome"},{"tipo":"texto","valor":", "},{"tipo":"campo","chave":"manual.conjuge_nacionalidade"},{"tipo":"texto","valor":", "},{"tipo":"campo","chave":"manual.conjuge_estado_civil"},{"tipo":"texto","valor":", "},{"tipo":"campo","chave":"manual.conjuge_profissao"},{"tipo":"texto","valor":", inscrito no CPF de n.º "},{"tipo":"campo","chave":"manual.conjuge_cpf"},{"tipo":"texto","valor":", domiciliado na "},{"tipo":"campo","chave":"manual.conjuge_endereco"},{"tipo":"texto","valor":", Brasil, ambos casados pelo regime de "},{"tipo":"campo","chave":"manual.regime"},{"tipo":"texto","valor":", vêm, por intermédio de seu advogado, com fundamento no 731 do Código de Processo Civil, propor ação cível de conhecimento de homologação de divórcio consensual."}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"h2","itens":[{"tipo":"texto","valor":"1. "},{"tipo":"texto","valor":"Fatos"}]},{"tipo":"elemento","tag":"h3","itens":[{"tipo":"campo","chave":"manual.trecho_14_1_1"}]},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Os requerentes, "},{"tipo":"campo","chave":"cliente.nome"},{"tipo":"texto","valor":" e "},{"tipo":"campo","chave":"manual.conjuge_nome"},{"tipo":"texto","valor":", estão casados sob o regime de "},{"tipo":"campo","chave":"manual.regime"},{"tipo":"texto","valor":", desde "},{"tipo":"campo","chave":"manual.data_casamento"},{"tipo":"texto","valor":", conforme consta em documento anexo. Deste matrimônio, as partes tiveram "},{"tipo":"campo","chave":"manual.quantidade_filhos"},{"tipo":"texto","valor":" filhos, sendo eles "},{"tipo":"campo","chave":"manual.nome_filho"},{"tipo":"texto","valor":", nascido na data de "},{"tipo":"campo","chave":"manual.nascimento_filho"},{"tipo":"texto","valor":"."}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Em razão disso, em consenso, o casal entendeu pela necessidade de fixar alimentos aos menores, definindo o valor de "},{"tipo":"campo","chave":"manual.valor_alimentos"},{"tipo":"texto","valor":" ("},{"tipo":"campo","chave":"manual.percentual_alimentos"},{"tipo":"texto","valor":"% do salário mínimo federal) a ser pago pelo genitor ao infante, todo dia "},{"tipo":"campo","chave":"manual.dia_alimentos"},{"tipo":"elemento","tag":"span","itens":[{"tipo":"texto","valor":" ("},{"tipo":"campo","chave":"manual.desconto_folha"},{"tipo":"texto","valor":")"}],"modelo_condicao":"m_incluir_desconto_folha:Sim"},{"tipo":"texto","valor":"."}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Entre o consortes, no entanto, dispensaram-se reciprocamente da obriga-ção de prestar quaisquer mensalidades alimentícias."}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Da mesma maneira, os cônjuges, acordam que: a residência, será fixada no lar materno; a guarda das crianças, será exercida na modalidade compartilhada; as visitas paternas, se darão de forma livre, havendo a mera formalidade de aviso prévio, bem se compreendendo a necessidade de respeito à rotina e cotidiano da prole."}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Durante a vigência do casamento, as partes adquiriram os seguintes bens:"}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"1.1. "},{"tipo":"campo","chave":"manual.trecho_20_1_1"},{"tipo":"texto","valor":";"}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"1.2. "},{"tipo":"campo","chave":"manual.trecho_21_1_1"},{"tipo":"texto","valor":";"}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"1.3. "},{"tipo":"campo","chave":"manual.trecho_22_1_1"},{"tipo":"texto","valor":";"}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"De comum acordo, as partes decidiram por partilhar os bens, assim, "},{"tipo":"campo","chave":"cliente.nome"},{"tipo":"texto","valor":" ficará com os "},{"tipo":"campo","chave":"manual.bens_cliente"},{"tipo":"texto","valor":", enquanto "},{"tipo":"campo","chave":"manual.conjuge_nome"},{"tipo":"texto","valor":" ficará com o "},{"tipo":"campo","chave":"manual.bens_conjuge"},{"tipo":"texto","valor":"."}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Por fim, a requerente virago deixará de usar o nome "},{"tipo":"campo","chave":"manual.nome_casada"},{"tipo":"texto","valor":", tornando a voltar o nome de quando era solteira "},{"tipo":"campo","chave":"manual.nome_solteira"},{"tipo":"texto","valor":"."}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"h2","itens":[{"tipo":"texto","valor":"2. "},{"tipo":"texto","valor":"Fundamentos"}]},{"tipo":"elemento","tag":"h2","itens":[{"tipo":"texto","valor":"2.1. "},{"tipo":"texto","valor":"Processo Eletrônico e Seus Atos"}]},{"tipo":"elemento","tag":"h3","itens":[{"tipo":"texto","valor":"Faculta-se pela adoção do “Juízo 100% Digital” – Resolução CNJ de n.º 345/2020"}]},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"O Código de Processo Civil traz consigo os arts. 193 ao 199 focando na possibilidade da prática eletrônica de atos processuais, delegando ao Conselho Nacional de Justiça, e, supletivamente aos Tribunais o dever de regulamentação."}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Em razão disso, o Conselho Nacional de Justiça resolveu por editar a resolução CNJ de n.º 345/2010, a qual faculta aos jurisdicionados a possibilidade de escolha pelo “Juízo 100% Digital”."}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Assim, elege-se o Juízo 100% Digital, prezando-se pela celeridade, eficiência e razoável duração do processo, solicitando-se que as audiências vindouras sejam telepresenciais"},{"tipo":"elemento","tag":"sup","itens":[{"tipo":"texto","valor":"1"}]},{"tipo":"texto","valor":"."}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"h2","itens":[{"tipo":"texto","valor":"2.2. "},{"tipo":"texto","valor":"Audiência de Mediação"}]},{"tipo":"elemento","tag":"h3","itens":[{"tipo":"texto","valor":"Desnecessidade da realização do ato"}]},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Visto que as partes já estão concordes antes mesmo do início do processo, dispensa-se a realização de audiência de mediação, como possibilita os art. 319, VII, e art. 334, §4º, I, do Código de Processo Civil"},{"tipo":"elemento","tag":"sup","itens":[{"tipo":"texto","valor":"2"}]},{"tipo":"texto","valor":"."}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"h2","itens":[{"tipo":"texto","valor":"2.3. "},{"tipo":"texto","valor":"O Casamento"}]},{"tipo":"elemento","tag":"h3","itens":[{"tipo":"texto","valor":"A dissolução do vínculo/sociedade conjugal pelo divórcio"}]},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"O casamento, estabelece vínculo entre as partes, com direitos e deveres inerentes ao instituto, nos termos dos arts. 1.511 e 1.565, do Código Civil:"}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Art. 1.511. O casamento estabelece comunhão plena de vida, com base na igualdade de direitos e deveres dos cônjuges."}],"classe":"doc-alinhar-justificar doc-recuo-1"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"(...)"}],"classe":"doc-alinhar-justificar doc-recuo-1"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Art. 1.565. Pelo casamento, homem e mulher assumem mutuamente a condição de consortes, companheiros e responsáveis pelos encargos da família."}],"classe":"doc-alinhar-justificar doc-recuo-1"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"A extinção deste vínculo, se dá no formato do art. 1.571, do mesmo Código:"}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Art. 1.571. A sociedade conjugal termina:"}],"classe":"doc-alinhar-justificar doc-recuo-1"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"I - pela morte de um dos cônjuges;"}],"classe":"doc-alinhar-justificar doc-recuo-1"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"II - pela nulidade ou anulação do casamento;"}],"classe":"doc-alinhar-justificar doc-recuo-1"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"III - pela separação judicial;"}],"classe":"doc-alinhar-justificar doc-recuo-1"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"IV - pelo divórcio. (grifos nossos)"}],"classe":"doc-alinhar-justificar doc-recuo-1"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Esse termo posto à relação matrimonial, é, inclusive, autorizado pelo Texto Constitucional, como fundamenta o seu art. 226, §6º"},{"tipo":"elemento","tag":"sup","itens":[{"tipo":"texto","valor":"3"}]},{"tipo":"texto","valor":". O divórcio consensual, ora aqui proposto, é um procedimento de jurisdição voluntária, e o art. 731 da Lei Civil possibilita:"}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Art. 731. A homologação do divórcio ou da separação consensuais, observados os requisitos legais, poderá ser requerida em petição assinada por ambos os cônjuges, da qual constarão:"}],"classe":"doc-alinhar-justificar doc-recuo-1"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"I - as disposições relativas à descrição e à partilha dos bens comuns;"}],"classe":"doc-alinhar-justificar doc-recuo-1"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"II - as disposições relativas à pensão alimentícia entre os cônjuges;"}],"classe":"doc-alinhar-justificar doc-recuo-1"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"III - o acordo relativo à guarda dos filhos incapazes e ao regime de visitas; e"}],"classe":"doc-alinhar-justificar doc-recuo-1"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"IV - o valor da contribuição para criar e educar os filhos."}],"classe":"doc-alinhar-justificar doc-recuo-1"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Parágrafo único. Se os cônjuges não acordarem sobre a partilha dos bens, far-se-á esta depois de homologado o divórcio, na forma estabelecida nos arts. 647 a 658."}],"classe":"doc-alinhar-justificar doc-recuo-1"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Daí a liberdade e a responsabilidade de convergirem as partes a respeito dos filhos, da residência, da guarda, das visitas, dos alimentos, dos bens e da partilha."}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"h2","itens":[{"tipo":"texto","valor":"2.4. "},{"tipo":"texto","valor":"A Criação dos Filhos"}]},{"tipo":"elemento","tag":"h3","itens":[{"tipo":"texto","valor":"O direito/dever em cuidar da residência, da guarda, das visitas e dos alimentos aos filhos"}]},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"A residência, nada mais é do que o local de moradia e habitação da criança, como se delineou ao narrar os fatos. A guarda, por outro lado, implica em responsabilidade, advinda do poder familiar"},{"tipo":"elemento","tag":"sup","itens":[{"tipo":"texto","valor":"4"}]},{"tipo":"texto","valor":", e pode ser exercida na modalidade unilateral ou compartilhada, como especifica o art. 1.583, da Norma Civil:"}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Art. 1.583.  A guarda será unilateral ou compartilhada. (Redação dada pela Lei nº 11.698, de 2008)."}],"classe":"doc-alinhar-justificar doc-recuo-1"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"§1º Compreende-se por guarda unilateral a atribuída a um só dos genitores ou a alguém que o substitua (art. 1.584, §5º) e, por guarda compartilhada a responsabilização conjunta e o exercício de direitos e deveres do pai e da mãe que não vivam sob o mesmo teto, concernentes ao poder familiar dos filhos comuns. "}],"classe":"doc-alinhar-justificar doc-recuo-1"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"§2º Na guarda compartilhada, o tempo de convívio com os filhos deve ser dividido de forma equilibrada com a mãe e com o pai, sempre tendo em vista as condições fáticas e os interesses dos filhos. "}],"classe":"doc-alinhar-justificar doc-recuo-1"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"§3º  Na guarda compartilhada, a cidade considerada base de moradia dos filhos será aquela que melhor atender aos interesses dos filhos. "}],"classe":"doc-alinhar-justificar doc-recuo-1"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"§4º (VETADO) ."}],"classe":"doc-alinhar-justificar doc-recuo-1"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"§5º  A guarda unilateral obriga o pai ou a mãe que não a detenha a supervisionar os interesses dos filhos, e, para possibilitar tal supervisão, qualquer dos genitores sempre será parte legítima para solicitar informações e/ou prestação de contas, objetivas ou subjetivas, em assuntos ou situações que direta ou indiretamente afetem a saúde física e psicológica e a educação de seus filhos. "}],"classe":"doc-alinhar-justificar doc-recuo-1"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Nesse sentido, visando o melhor interesse e o bem-estar das crianças, estabelecida a residência com um dos pais, deve-se viabilizar o contato da prole com a outra parte, seja o pai ou a mãe, obedecendo as premissas dos arts. 227 e 229, ambos da Constituição Federal – justificando o que convencionaram as partes nos fatos expostos."}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"A prestação alimentícia, funda-se não apenas nos artigos constitucionais supra, mas também na legislação infraconstitucional, o Código Civil, haja vista o art. 1.694"},{"tipo":"elemento","tag":"sup","itens":[{"tipo":"texto","valor":"5"}]},{"tipo":"texto","valor":" e seguintes, e, semelhantemente, o Estatuto da Criança e do Adolescente em seu art. 22:"}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Art. 22. Aos pais incumbe o dever de sustento, guarda e educação dos filhos menores, cabendo-lhes ainda, no interesse destes, a obrigação de cumprir e fazer cumprir as determinações judiciais."}],"classe":"doc-alinhar-justificar doc-recuo-1"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Parágrafo único.  A mãe e o pai, ou os responsáveis, têm direitos iguais e deveres e responsabilidades compartilhados no cuidado e na educação da criança, devendo ser resguardado o direito de transmissão familiar de suas crenças e culturas, assegurados os direitos da criança estabelecidos nesta Lei."}],"classe":"doc-alinhar-justificar doc-recuo-1"},{"tipo":"elemento","tag":"h2","itens":[{"tipo":"texto","valor":"2.5. "},{"tipo":"texto","valor":"Alimentos entre Cônjuges"}]},{"tipo":"elemento","tag":"h3","itens":[{"tipo":"texto","valor":"A extensão do dever de assistência mútua"}]},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"O referido art. 1.694 do Código Civil, permite que parentes, cônjuges e/ou companheiros peçam alimentos uns dos outros, bastando que o peticionante não tenha bens e/ou meios suficientes para prover, pelo próprio trabalho, sua subsistência."}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Além disso, atentos aos efeitos do casamento, temos:"}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Art. 1.566. São deveres de ambos os cônjuges:"}],"classe":"doc-alinhar-justificar doc-recuo-1"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"I - fidelidade recíproca;"}],"classe":"doc-alinhar-justificar doc-recuo-1"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"II - vida em comum, no domicílio conjugal;"}],"classe":"doc-alinhar-justificar doc-recuo-1"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"III - mútua assistência;"}],"classe":"doc-alinhar-justificar doc-recuo-1"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"IV - sustento, guarda e educação dos filhos;"}],"classe":"doc-alinhar-justificar doc-recuo-1"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"V - respeito e consideração mútuos. (grifos nossos)"}],"classe":"doc-alinhar-justificar doc-recuo-1"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Assim, ainda que findada a sociedade conjugal pelo divórcio, não se pode preterir a relação mutualística, pretérita e atual, entre o casal, até mesmo neste momento de divórcio, razão pela qual as partes, em comum consenso, acordam por estipular alimentos em favor da parte que os necessita, como já mencionado."}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"h2","itens":[{"tipo":"texto","valor":"3. "},{"tipo":"texto","valor":"Pedidos"}]},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Pelo arrazoado, requer-se:"}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"2.1. "},{"tipo":"texto","valor":"Prefacialmente, por ser matéria que versa sobre divórcio, pelo trâmite em segredo de justiça, nos termos do art. 189, II, do Código de Processo Civil;"}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"2.2. "},{"tipo":"texto","valor":"Em seguida, seja deferido o pleito de justiça gratuita, como alinha o art. 98, também do Código de Processo Civil;"}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"2.3. "},{"tipo":"texto","valor":"A produção de todos os meios de provas admitidos em direito, conforme art. 369, da Lei Processual;"}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"2.4. "},{"tipo":"texto","valor":"Sem prejuízo, seja intimado o Ministério Público, na qualidade de fiscal da lei, para que se manifeste quanto ao seu interesse/legitimidade para atuar no feito;"}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"2.5. "},{"tipo":"texto","valor":"Ao fim, pela procedência da presente ação, com o fito de decretar o divórcio do casal, e por conseguinte, homologar todas as disposições relativas à residência, à guarda, às visitas e aos alimentos nas mesmas linhas ventiladas;"}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"2.6. "},{"tipo":"texto","valor":"Com a procedência dos pedidos, seja oficiado mandado de averbação ao Cartório de Registro Civil local, para que promova todas as devidas anotações;"}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Dá-se à causa o valor de "},{"tipo":"campo","chave":"manual.valor_causa"},{"tipo":"texto","valor":", nos termos do art. 292, II, III e VI, do Código de Processo Civil."}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Paranaguá|PR, datado e assinado digitalmente,"}],"classe":"doc-data"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"campo","chave":"advogado.nome"}],"classe":"doc-alinhar-centro"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"OAB|PR "},{"tipo":"campo","chave":"advogado.oab_numero"}],"classe":"doc-alinhar-centro"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Advogado"}],"classe":"doc-alinhar-centro"},{"tipo":"elemento","tag":"hr","itens":[],"classe":"doc-nota"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"elemento","tag":"sup","itens":[{"tipo":"texto","valor":"1"}]},{"tipo":"texto","valor":" Como instrui a resolução CNJ de n.º 354/2020."}],"classe":"doc-alinhar-justificar doc-nota"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"elemento","tag":"sup","itens":[{"tipo":"texto","valor":"2"}]},{"tipo":"texto","valor":" “Art. 319. A petição inicial indicará: (...) VII - a opção do autor pela realização ou não de audiência de conciliação ou de mediação."}],"classe":"doc-alinhar-justificar doc-nota"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"(...)"}],"classe":"doc-alinhar-justificar doc-nota"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Art. 334. Se a petição inicial preencher os requisitos essenciais e não for o caso de improcedência liminar do pedido, o juiz designará audiência de conciliação ou de mediação com antecedência mínima de 30 (trinta) dias, devendo ser citado o réu com pelo menos 20 (vinte) dias de antecedência. (...) § 4º A audiência não será realizada: I - se ambas as partes manifestarem, expressamente, desinteresse na composição consensual; II - quando não se admitir a autocomposição.”"}],"classe":"doc-alinhar-justificar doc-nota"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"elemento","tag":"sup","itens":[{"tipo":"texto","valor":"3"}]},{"tipo":"texto","valor":" “Art. 226. A família, base da sociedade, tem especial proteção do Estado. (...) § 6º O casamento civil pode ser dissolvido pelo divórcio.”"}],"classe":"doc-alinhar-justificar doc-nota"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"elemento","tag":"sup","itens":[{"tipo":"texto","valor":"4"}]},{"tipo":"texto","valor":" “Art. 1.634.  Compete a ambos os pais, qualquer que seja a sua situação conjugal, o pleno exercício do poder fami-liar, que consiste em, quanto aos filhos: I - dirigir-lhes a criação e a educação; II - exercer a guarda unilateral ou compartilhada nos termos do art. 1.584; III - conceder-lhes ou negar-lhes consentimento para casarem; IV - conceder-lhes ou negar-lhes consentimento para viajarem ao exterior; V - conceder-lhes ou negar-lhes consentimento para mudarem sua residência permanente para outro Município; VI - nomear-lhes tutor por testamento ou documento autêntico, se o outro dos pais não lhe sobreviver, ou o sobre-vivo não puder exercer o poder familiar; VII - representá-los judicial e extrajudicialmente até os 16 (dezesseis) anos, nos atos da vida civil, e assisti-los, após essa idade, nos atos em que forem partes, suprindo-lhes o consentimento; VIII - reclamá-los de quem ilegalmente os detenha;”"}],"classe":"doc-alinhar-justificar doc-nota"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"elemento","tag":"sup","itens":[{"tipo":"texto","valor":"5"}]},{"tipo":"texto","valor":" “Art. 1.694. Podem os parentes, os cônjuges ou companheiros pedir uns aos outros os alimentos de que necessitem para viver de modo compatível com a sua condição social, inclusive para atender às necessidades de sua educação.”"}],"classe":"doc-alinhar-justificar doc-nota"}],"perguntas":[{"chave":"manual.juizo","rotulo":"Juízo ou vara","tipo":"texto","obrigatorio":true},{"chave":"manual.assunto","rotulo":"Assunto da petição","tipo":"texto","obrigatorio":true},{"chave":"manual.urgencia_detalhe","rotulo":"Motivo da urgência","tipo":"texto","obrigatorio":true},{"chave":"manual.nota_5","rotulo":"URGÊNCIA","tipo":"escolha","obrigatorio":false,"opcoes":["Não","Sim"]},{"chave":"manual.nota_6","rotulo":"Prioridade +60","tipo":"escolha","obrigatorio":false,"opcoes":["Não","Sim"]},{"chave":"manual.trecho_7_1_1","rotulo":"Trecho após “Sigiloso, conforme art. 189,”","tipo":"texto","obrigatorio":true},{"chave":"manual.nota_7","rotulo":"Sigiloso","tipo":"escolha","obrigatorio":false,"opcoes":["Não","Sim"]},{"chave":"manual.mov_gratuidade","rotulo":"Movimento em que a gratuidade foi deferida","tipo":"texto","obrigatorio":true},{"chave":"manual.nota_8","rotulo":"Gratuidade da justiça deferida","tipo":"escolha","obrigatorio":false,"opcoes":["Não","Sim"]},{"chave":"manual.nota_9","rotulo":"Há interesse na audiência de conciliação/mediação","tipo":"escolha","obrigatorio":false,"opcoes":["Não","Sim"]},{"chave":"manual.ementa","rotulo":"Ementa","tipo":"texto_longo","obrigatorio":false},{"chave":"manual.conjuge_nome","rotulo":"Nome · cônjuge","tipo":"texto","obrigatorio":true},{"chave":"manual.conjuge_nacionalidade","rotulo":"Nacionalidade · cônjuge","tipo":"texto","obrigatorio":true},{"chave":"manual.conjuge_estado_civil","rotulo":"Estado civil · cônjuge","tipo":"escolha","obrigatorio":true,"opcoes":["solteiro","solteira","em união estável","casado","casada","divorciado","divorciada","viúvo","viúva"]},{"chave":"manual.conjuge_profissao","rotulo":"Profissão · cônjuge","tipo":"texto","obrigatorio":true},{"chave":"manual.conjuge_cpf","rotulo":"CPF · cônjuge","tipo":"texto","obrigatorio":true},{"chave":"manual.conjuge_endereco","rotulo":"Endereço · cônjuge","tipo":"texto","obrigatorio":true},{"chave":"manual.regime","rotulo":"Regime de bens","tipo":"escolha","obrigatorio":true,"opcoes":["separação total de bens","comunhão parcial de bens","comunhão universal de bens","participação final nos aquestos"]},{"chave":"manual.trecho_14_1_1","rotulo":"Subtítulo da seção Fatos","tipo":"texto","obrigatorio":true},{"chave":"manual.data_casamento","rotulo":"Data do casamento","tipo":"data","obrigatorio":true},{"chave":"manual.quantidade_filhos","rotulo":"Quantidade de filhos","tipo":"inteiro","obrigatorio":true},{"chave":"manual.nome_filho","rotulo":"Nome do filho","tipo":"texto","obrigatorio":true},{"chave":"manual.nascimento_filho","rotulo":"Nascimento do filho","tipo":"texto","obrigatorio":true},{"chave":"manual.valor_alimentos","rotulo":"Valor dos alimentos","tipo":"valor","obrigatorio":true},{"chave":"manual.percentual_alimentos","rotulo":"Percentual do salário mínimo (só o número)","tipo":"texto","obrigatorio":true},{"chave":"manual.dia_alimentos","rotulo":"Dia do pagamento dos alimentos","tipo":"inteiro","obrigatorio":true},{"chave":"manual.desconto_folha","rotulo":"Condição do desconto em folha","tipo":"texto","obrigatorio":true},{"chave":"manual.incluir_desconto_folha","rotulo":"Há desconto em folha?","tipo":"escolha","obrigatorio":false,"opcoes":["Não","Sim"]},{"chave":"manual.trecho_20_1_1","rotulo":"Subtítulo da seção Fatos (2)","tipo":"texto","obrigatorio":true},{"chave":"manual.trecho_21_1_1","rotulo":"Subtítulo da seção Fatos (3)","tipo":"texto","obrigatorio":true},{"chave":"manual.trecho_22_1_1","rotulo":"Subtítulo da seção Fatos (4)","tipo":"texto","obrigatorio":true},{"chave":"manual.bens_cliente","rotulo":"Bens destinados ao cliente","tipo":"texto","obrigatorio":true},{"chave":"manual.bens_conjuge","rotulo":"Bens destinados ao cônjuge","tipo":"texto","obrigatorio":true},{"chave":"manual.nome_casada","rotulo":"Nome de casada","tipo":"texto","obrigatorio":true},{"chave":"manual.nome_solteira","rotulo":"Nome de solteira","tipo":"texto","obrigatorio":true},{"chave":"manual.valor_causa","rotulo":"Valor da causa","tipo":"valor","obrigatorio":true}],"assinaturas":[]}},{"chave":"carta_preposicao","tipo":"personalizado","categoria":"Mandato","nome":"Carta de Preposição","titulo":"CARTA DE PREPOSIÇÃO","fonte":"Carta de Preposição.docx","definicao":{"formato":1,"folha_origem":true,"corpo":[{"tipo":"elemento","tag":"h2","itens":[{"tipo":"texto","valor":"CARTA DE PREPOSIÇÃO"}],"classe":"doc-titulo"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"campo","chave":"cliente.nome"},{"tipo":"texto","valor":", pessoa jurídica de direito privado, inscrita no CNPJ de n.º "},{"tipo":"campo","chave":"cliente.cnpj"},{"tipo":"texto","valor":", "},{"tipo":"campo","chave":"cliente.domiciliado"},{"tipo":"texto","valor":" na "},{"tipo":"campo","chave":"cliente.endereco"},{"tipo":"texto","valor":", neste ato representada pelo(a) sócio(a) "},{"tipo":"campo","chave":"manual.representante_nome"},{"tipo":"texto","valor":", "},{"tipo":"campo","chave":"manual.representante_nacionalidade"},{"tipo":"texto","valor":", "},{"tipo":"campo","chave":"manual.representante_estado_civil"},{"tipo":"texto","valor":", empresário(a), inscrito no CPF de nº "},{"tipo":"campo","chave":"manual.representante_cpf"},{"tipo":"texto","valor":", domiciliado(a) na "},{"tipo":"campo","chave":"manual.representante_endereco"},{"tipo":"texto","valor":", nomeia e constitui como preposto "},{"tipo":"campo","chave":"manual.preposto_nome"},{"tipo":"texto","valor":", "},{"tipo":"campo","chave":"manual.preposto_nacionalidade"},{"tipo":"texto","valor":", "},{"tipo":"campo","chave":"manual.preposto_estado_civil"},{"tipo":"texto","valor":", "},{"tipo":"campo","chave":"manual.preposto_profissao"},{"tipo":"texto","valor":", inscrito no CPF de nº "},{"tipo":"campo","chave":"manual.preposto_cpf"},{"tipo":"texto","valor":", para que represente esta pessoa jurídica nos atos e audiências dos autos de n.º "},{"tipo":"campo","chave":"oficial.autos"},{"tipo":"texto","valor":"."}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Declara também que o(a) preposto(a) integra ao quadro funcional da empresa e possui conhecimento dos fatos narrados na inicial, atendendo assim às exigências legais previstas no §1º do art. 843 da CLT, bem como à jurisprudência consolidada do Tribunal Superior do Trabalho, que admite a representação por pessoa que detenha conhecimento dos fatos, ainda que não exerça função de gestão."}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Paranaguá|PR, "},{"tipo":"campo","chave":"emissao.data"},{"tipo":"texto","valor":","}],"classe":"doc-data"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"elemento","tag":"br","itens":[]}],"classe":"doc-alinhar-justificar"},{"tipo":"elemento","tag":"table","itens":[{"tipo":"elemento","tag":"tbody","itens":[{"tipo":"elemento","tag":"tr","itens":[{"tipo":"elemento","tag":"td","itens":[{"tipo":"elemento","tag":"p","itens":[{"tipo":"ele