,{"chave":"manual.testemunha_2_nome","rotulo":"Nome da testemunha 2","tipo":"texto","obrigatorio":true},{"chave":"manual.testemunha_2_qualificacao","rotulo":"Qualificação da testemunha 2","tipo":"texto_longo","obrigatorio":true},{"chave":"manual.incluir_testemunha_2","rotulo":"Incluir testemunha 2?","tipo":"escolha","obrigatorio":false,"opcoes":["Não","Sim"]},{"chave":"manual.testemunha_3_nome","rotulo":"Nome da testemunha 3","tipo":"texto","obrigatorio":true},{"chave":"manual.testemunha_3_qualificacao","rotulo":"Qualificação da testemunha 3","tipo":"texto_longo","obrigatorio":true},{"chave":"manual.incluir_testemunha_3","rotulo":"Incluir testemunha 3?","tipo":"escolha","obrigatorio":false,"opcoes":["Não","Sim"]}],"assinaturas":[]}},{"chave":"peticao_aceite_dativo","tipo":"personalizado","categoria":"Petição","nome":"Petição Intermediária - Aceite dativo, prazo e prerrogativas","titulo":"Petição Intermediária - Aceite dativo, prazo e prerrogativas","fonte":"Petição Intermediária - Aceite dativo. Prazo. Prerrogativas..docx","definicao":{"formato":1,"folha_origem":true,"corpo":[{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Ao Juízo "},{"tipo":"campo","chave":"oficial.juizo_docx"},{"tipo":"texto","valor":"|PR,"}],"classe":"doc-alinhar-esquerda"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Autos de n.º "},{"tipo":"campo","chave":"processo.autos"},{"tipo":"texto","valor":","}],"classe":"doc-alinhar-justificar"},{"tipo":"elemento","tag":"h2","itens":[{"tipo":"texto","valor":"Aceite da nomeação, prazo complementar para análise e manifestação, e observância das prerrogativas que se estendem ao advogado dativo,"}],"classe":"doc-alinhar-esquerda doc-titulo"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"elemento","tag":"br","itens":[]}],"classe":"doc-alinhar-justificar"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"URGÊNCIA – "},{"tipo":"campo","chave":"manual.urgencia_detalhe"}],"classe":"doc-alinhar-justificar","modelo_condicao":"m_nota_5:Sim"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Prioridade +60, de acordo com o art. 71 da Lei 10.741/2003."}],"classe":"doc-alinhar-justificar","modelo_condicao":"m_nota_6:Sim"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Sigiloso, conforme art. 189, "},{"tipo":"campo","chave":"manual.trecho_7_1_1"},{"tipo":"texto","valor":", da Lei 13.105/2015."}],"classe":"doc-alinhar-justificar","modelo_condicao":"m_nota_7:Sim"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Gratuidade da justiça deferida em mov. "},{"tipo":"campo","chave":"manual.mov_gratuidade"},{"tipo":"texto","valor":"."}],"classe":"doc-alinhar-justificar","modelo_condicao":"m_nota_8:Sim"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Há interesse na audiência de conciliação/mediação."}],"classe":"doc-alinhar-justificar","modelo_condicao":"m_nota_9:Sim"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"elemento","tag":"br","itens":[]}],"classe":"doc-alinhar-justificar"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Eu, "},{"tipo":"campo","chave":"advogado.nome"},{"tipo":"texto","valor":", advogado, inscrito na OAB/PR de n.º "},{"tipo":"campo","chave":"advogado.oab_numero"},{"tipo":"texto","valor":", recebo e aceito com honra a nomeação para atuação nestes autos na qualidade de advogado dativo."}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Previamente, em cuidado às garantias e princípios do contraditório e ampla defesa, e, em especial respeito ao assistido, a defesa pede pelo prazo complementar de "},{"tipo":"campo","chave":"manual.trecho_12_1_1"},{"tipo":"texto","valor":" dias para adequada análise e manifestação."}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Ainda, considerando que a advocacia dativa exerce função que cabe ao Estado, fazendo cumprir o art. 5º, LXXIV, da Constituição Federal, postula-se que sejam estendidas e observadas todas as prerrogativas da Defensoria Pública a advocacia dativa."}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Tais pedidos e cautelas não se desgarram do entendimento jurisprudencial do Superior Tribunal de Justiça, que à sua luz:"}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"CIVIL. PROCESSUAL CIVIL. RECURSO ORDINÁRIO CONSTITUCIONAL EM MANDADO DE SEGURANÇA. INTIMAÇÃO PESSOAL DA PARTE ASSISTIDA PELA DEFENSORIA PÚBLICA. EXTENSÃO DA PRERROGATIVA AO DEFENSOR DATIVO. POSSIBILIDADE. INTERPRETAÇÃO SISTEMÁTICA E TELEOLÓGICA DO ART. 186, §2º, DO CPC/15. AUSÊNCIA DE RAZÃO JURÍDICA PLAUSÍVEL PARA TRATAMENTO DIFERENCIADO ENTRE A DEFENSORIA PÚBLICA E O DEFENSOR DATIVO NA HIPÓTESES. PROBLEMAS DE COMUNICAÇÃO, DE OBTENÇÃO DE INFORMAÇÕES E EXCESSO DE CAUSAS, QUE JUSTIFICARAM A EDIÇÃO DA REGRA, QUE SÃO EXPERIMENTADOS POR AMBOS. INTERPRETAÇÃO LITERAL E RESTRITIVA QUE ACARRETARIA NOTÓRIO PREJUÍZO AO ASSISTIDO QUE A LEI PRETENDEU TUTELAR, COM VIOLAÇÃO DOS PRINCÍPIOS DO ACESSO À JUSTIÇA, DO CONTRADITÓRIO E DA AMPLA DEFESA. EXTENSÃO DA PRERROGATIVA AO DEFENSOR DATIVO PLENAMENTE JUSTIFICÁVEL. INTIMAÇÃO PESSOAL DA PARTE ASSISTIDA. EXIGÊNCIA DE QUE HAJA PROVIDÊNCIA A SER POR ELA REALIZADA OU INFORMAÇÃO A SER POR ELA PRESTADA. EXERCÍCIO DO DIREITO DE RECORRER CONTRA A SENTENÇA PARCIALMENTE DESFAVORÁVEL AO ASSISTIDO. DESNECESSIDADE DA INTIMAÇÃO PESSOAL DO ASSISTIDO. MANDATO COM PODERES GERAIS DA CLÁUSULA AD JUDICIA. AUTORIZAÇÃO PARA A PRÁTICA DE TODOS OS ATOS PROCESSUAIS NECESSÁRIOS À DEFESA DO ASSISTIDO, INCLUSIVE RECORRER. "}],"classe":"doc-alinhar-justificar doc-recuo-1"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"1- O propósito recursal é definir se é admissível a extensão da prerrogativa conferida à Defensoria Pública, de requerer a intimação pessoal da parte na hipótese do art. 186, §2º, do CPC/15, também ao defensor dativo nomeado em virtude de convênio celebrado entre a OAB e a Defensoria e se, na hipótese, estão presentes os pressupostos para o deferimento da intimação pessoal da parte assistida. "}],"classe":"doc-alinhar-justificar doc-recuo-1"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"2- A interpretação literal das regras contidas do art. 186, caput, §2º e §3º, do CPC/15, autorizaria a conclusão de apenas a prerrogativa de cômputo em dobro dos prazos prevista no caput seria extensível ao defensor dativo, mas não a prerrogativa de requerer a intimação pessoal da parte assistida quando o ato processual depender de providência ou informação que somente por ela possa ser realizada ou prestada."}],"classe":"doc-alinhar-justificar doc-recuo-1"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"3- Esse conjunto de regras, todavia, deve ser interpretado de modo sistemático e à luz de sua finalidade, a fim de se averiguar se há razão jurídica plausível para que se trate a Defensoria Pública e o defensor dativo de maneira anti-isonômica. "}],"classe":"doc-alinhar-justificar doc-recuo-1"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"4- Dado que o defensor dativo atua em locais em que não há Defensoria Pública instalada, cumprindo o quase altruísta papel de garantir efetivo e amplo acesso à justiça aqueles mais necessitados, é correto afirmar que as mesmas dificuldades de comunicação e de obtenção de informações, dados e documentos, experimentadas pela Defensoria Pública e que justificaram a criação do art. 186, §2º, do CPC/15, são igualmente frequentes em relação ao defensor dativo. "}],"classe":"doc-alinhar-justificar doc-recuo-1"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"5- É igualmente razoável concluir que a altíssima demanda recebida pela Defensoria Pública, que pressiona a instituição a tratar de muito mais causas do que efetivamente teria capacidade de receber, também se verifica quanto ao defensor dativo, especialmente porque se trata de profissional remunerado de maneira módica e que, em virtude disso, naturalmente precisa assumir uma quantidade significativa de causas para que obtenha uma remuneração digna e compatível. "}],"classe":"doc-alinhar-justificar doc-recuo-1"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"6- A interpretação literal e restritiva da regra em exame, a fim de excluir do seu âmbito de incidência o defensor dativo, prejudicará justamente o assistido necessitado que a regra pretendeu tutelar, ceifando a possibilidade de, pessoalmente intimado, cumprir determinações e fornecer subsídios, em homenagem ao acesso à justiça, ao contraditório e à ampla defesa, razão pela qual deve ser admitida a extensão da prerrogativa conferida à Defensoria Pública no art. 186, §2º, do CPC/15, também ao defensor dativo nomeado em virtude de convênio celebrado entre a OAB e a Defensoria."}],"classe":"doc-alinhar-justificar doc-recuo-1"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"7- Segundo o art. 186, §2º, do CPC/15, a intimação pessoal da parte assistida pressupõe uma providência que apenas por ela possa ser realizada ou uma informação que somente por ela possa ser prestada, como, por exemplo, indicar as testemunhas a serem arroladas, exibir documento por força de ordem judicial, cumprir a sentença (art. 513, §2º, II, do CPC/15) e ser cientificado do requerimento, pelo exequente, de adjudicação do bem penhorado (art. 876, §1º, II, do CPC/15). (...) "}],"classe":"doc-alinhar-justificar doc-recuo-1"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"(STJ - RECURSO EM MANDADO DE SEGURANÇA Nº 64.894 – SP - RELATORA: MINISTRA NANCY ANDRIGHI – DJ 2021)"}],"classe":"doc-alinhar-justificar doc-recuo-1"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Paranaguá|PR, datado e assinado digitalmente,"}],"classe":"doc-data"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"campo","chave":"advogado.nome"}],"classe":"doc-alinhar-centro"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"OAB|PR "},{"tipo":"campo","chave":"advogado.oab_numero"}],"classe":"doc-alinhar-centro"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Advogado"}],"classe":"doc-alinhar-centro"}],"perguntas":[{"chave":"manual.juizo","rotulo":"Juízo ou vara","tipo":"texto","obrigatorio":true},{"chave":"manual.autos","rotulo":"Número dos autos","tipo":"texto","obrigatorio":false},{"chave":"manual.urgencia_detalhe","rotulo":"Motivo da urgência","tipo":"texto","obrigatorio":true},{"chave":"manual.nota_5","rotulo":"URGÊNCIA","tipo":"escolha","obrigatorio":false,"opcoes":["Não","Sim"]},{"chave":"manual.nota_6","rotulo":"Prioridade +60","tipo":"escolha","obrigatorio":false,"opcoes":["Não","Sim"]},{"chave":"manual.trecho_7_1_1","rotulo":"Trecho após “Sigiloso, conforme art. 189,”","tipo":"texto","obrigatorio":true},{"chave":"manual.nota_7","rotulo":"Sigiloso","tipo":"escolha","obrigatorio":false,"opcoes":["Não","Sim"]},{"chave":"manual.mov_gratuidade","rotulo":"Movimento em que a gratuidade foi deferida","tipo":"texto","obrigatorio":true},{"chave":"manual.nota_8","rotulo":"Gratuidade da justiça deferida","tipo":"escolha","obrigatorio":false,"opcoes":["Não","Sim"]},{"chave":"manual.nota_9","rotulo":"Há interesse na audiência de conciliação/mediação","tipo":"escolha","obrigatorio":false,"opcoes":["Não","Sim"]},{"chave":"manual.trecho_12_1_1","rotulo":"Trecho após “defesa pede pelo prazo complementar de”","tipo":"texto","obrigatorio":true}],"assinaturas":[]}},{"chave":"peticao_especificacao_provas","tipo":"personalizado","categoria":"Petição","nome":"Petição Intermediária - Especificação de provas","titulo":"Petição Intermediária - Especificação de provas","fonte":"Petição Intermediária - Especificação de provas.docx","definicao":{"formato":1,"folha_origem":true,"corpo":[{"tipo":"elemento","t