ve":"manual.evento_p_17","rotulo":"Número do evento após “Intimado em evento”","tipo":"texto","obrigatorio":true},{"chave":"manual.redacao_18","rotulo":"Corpo da petição · texto 4 (opcional)","tipo":"texto_longo","obrigatorio":false},{"chave":"manual.redacao_19","rotulo":"Corpo da petição · texto 5 (opcional)","tipo":"texto_longo","obrigatorio":false},{"chave":"manual.redacao_20","rotulo":"Corpo da petição · texto 6 (opcional)","tipo":"texto_longo","obrigatorio":false},{"chave":"manual.parte_peticao","rotulo":"Posição na petição","tipo":"escolha","obrigatorio":true,"opcoes":["Parte","Assistente de acusação"]}],"assinaturas":[]}},{"chave":"procuracao","tipo":"procuracao","categoria":"Mandato","nome":"Procuração","titulo":"PROCURAÇÃO","fonte":"Procuração.docx","definicao":{"formato":1,"folha_origem":true,"corpo":[{"tipo":"elemento","tag":"h2","itens":[{"tipo":"texto","valor":"PROCURAÇÃO"}],"classe":"doc-titulo"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"campo","chave":"cliente.nome"},{"tipo":"texto","valor":", "},{"tipo":"campo","chave":"cliente.nacionalidade"},{"tipo":"texto","valor":", "},{"tipo":"campo","chave":"cliente.estado_civil"},{"tipo":"texto","valor":", "},{"tipo":"campo","chave":"cliente.profissao"},{"tipo":"texto","valor":", "},{"tipo":"campo","chave":"cliente.inscrito"},{"tipo":"texto","valor":" no CPF de n.º "},{"tipo":"campo","chave":"cliente.cpf"},{"tipo":"texto","valor":", "},{"tipo":"campo","chave":"cliente.domiciliado"},{"tipo":"texto","valor":" na "},{"tipo":"campo","chave":"cliente.endereco"},{"tipo":"texto","valor":", Brasil, constitui como seus procuradores, os exmos. drs. Guilherme de Oliveira da Fonseca, advogado, inscrito na OAB/PR de n.º 116.072; Juliana Cristina da Silva Lisboa, advogada, inscrita na OAB/PR de n.º 117.141; Vinicius Rangel de Lima de Paula Lisboa, advogado, inscrito na OAB/PR de n.º 105.790, todos com escritório profissional localizado na rua Doutor Leocádio, 282, Centro, Paranaguá/PR – CEP: 83.203-270, telefone: (41) 2152-2607, outorgando-lhes poderes amplos, gerais e ilimitados para o foro em geral, ou onde com este se apresentarem em nome do outorgante, em juízo ou fora dele, como autor, réu, assistente ou oponente, podendo propor ou contestar ações ou participar de processos incidentes, preliminares, cautelares e acessórios(as), e especiais para a defesa de todo e qualquer interesse ou direito do outorgante, podendo os procuradores, para tal fim, requerer o que convier praticar; todos os atos necessários e inerentes ao presente mandato, podendo ingressar e participar de quaisquer reuniões e/ou assembleias, como fixam os arts. 4º, §2º, e, 7º,VI, d, ambos da Lei 8.906/1994, especialmente transigir para os devidos fins e efeitos do art. 359 do Lei 13.105/2015, intentar, de novo, receber e dar quitação, levantar quantias depositadas, inclusive fianças, firmar compromissos, fazer acordos, requerer falência do devedor, apresentar memoriais, representar o testamenteiro conforme art. 1.985, da Lei 10.406/2002; o inventariante, nos termos do art. 618, III, da Lei 13.105/2015; o ofendido nos termos do art. 39, podendo, inclusive oferecer ou renunciar a queixa, como instrui o art. 44 e 50, dar ou aceitar o perdão, na forma do art. 50 e 59, arguir exceção e/ou incidente, nos moldes do art. 98 e 146, todos do Decreto-Lei 3.689/1941, requerer ou apelar para qualquer instância ou tribunal até julgamento final, podendo, ainda, substabelecer este para outrem, com ou sem reserva de iguais poderes, e representar extrajudicialmente perante repartições públicas, federais, estaduais e municipais, autarquias, empresas públicas, sociedades de economia mista, estabelecimentos bancários e demais pessoas jurídicas de direito público ou privado, e requerer, quando e se necessário, a justiça gratuita, dando tudo por bom, firme e valioso."}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Paranaguá|PR, "},{"tipo":"campo","chave":"emissao.data"},{"tipo":"texto","valor":","}],"classe":"doc-data"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"elemento","tag":"br","itens":[]}],"classe":"doc-alinhar-justificar"},{"tipo":"elemento","tag":"table","itens":[{"tipo":"elemento","tag":"tbody","itens":[{"tipo":"elemento","tag":"tr","itens":[{"tipo":"elemento","tag":"td","itens":[{"tipo":"elemento","tag":"p","itens":[{"tipo":"elemento","tag":"br","itens":[]}],"classe":"doc-alinhar-justificar"}]}]},{"tipo":"elemento","tag":"tr","itens":[{"tipo":"elemento","tag":"td","itens":[{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Outorgante"}],"classe":"doc-rubrica"}]}]}]}],"classe":"doc-tabela"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"elemento","tag":"br","itens":[]}],"classe":"doc-alinhar-justificar"}],"perguntas":[],"assinaturas":[]}},{"chave":"recibo_docx","tipo":"personalizado","categoria":"Outros","nome":"Recibo","titulo":"RECIBO","fonte":"Recibo.docx","definicao":{"formato":1,"folha_origem":true,"corpo":[{"tipo":"elemento","tag":"h2","itens":[{"tipo":"texto","valor":"RECIBO"}],"classe":"doc-titulo"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Eu, "},{"tipo":"campo","chave":"advogado.nome"},{"tipo":"texto","valor":", advogado, inscrito no n.º "},{"tipo":"campo","chave":"advogado.oab_numero"},{"tipo":"texto","valor":" dos quadros da OAB/PR, declaro para os devidos fins legais que recebi de "},{"tipo":"campo","chave":"cliente.nome"},{"tipo":"texto","valor":" (CPF: "},{"tipo":"campo","chave":"cliente.cpf"},{"tipo":"texto","valor":"), em "},{"tipo":"campo","chave":"manual.data_pagamento"},{"tipo":"texto","valor":", o pagamento de honorários advocatícios na quantia de "},{"tipo":"campo","chave":"manual.valor_pago"},{"tipo":"texto","valor":"."}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Paranaguá|PR, "},{"tipo":"campo","chave":"emissao.data"},{"tipo":"texto","valor":","}],"classe":"doc-data"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"elemento","tag":"br","itens":[]}],"classe":"doc-alinhar-justificar"},{"tipo":"elemento","tag":"table","itens":[{"tipo":"elemento","tag":"tbody","itens":[{"tipo":"elemento","tag":"tr","itens":[{"tipo":"elemento","tag":"td","itens":[{"tipo":"elemento","tag":"p","itens":[{"tipo":"elemento","tag":"br","itens":[]}],"classe":"doc-alinhar-justificar"}]}]},{"tipo":"elemento","tag":"tr","itens":[{"tipo":"elemento","tag":"td","itens":[{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Declarante"}],"classe":"doc-rubrica"}]}]}]}],"classe":"doc-tabela"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"elemento","tag":"br","itens":[]}],"classe":"doc-alinhar-justificar"}],"perguntas":[{"chave":"manual.data_pagamento","rotulo":"Data do pagamento","tipo":"data","obrigatorio":true},{"chave":"manual.valor_pago","rotulo":"Valor pago","tipo":"valor","obrigatorio":true}],"assinaturas":[]}},{"chave":"renuncia","tipo":"renuncia","categoria":"Mandato","nome":"Renúncia de Mandato","titulo":"RENÚNCIA DE MANDATO","fonte":"Renúncia de Mandato.docx","definicao":{"formato":1,"folha_origem":true,"corpo":[{"tipo":"elemento","tag":"h2","itens":[{"tipo":"texto","valor":"RENÚNCIA DE MANDATO"}],"classe":"doc-titulo"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Nós, Guilherme de Oliveira da Fonseca, advogado, inscrito na OAB/PR de n.º 116.072; Juliana Cristina da Silva Lisboa, advogada, inscrita na OAB/PR de n.º 117.141; Vinicius Rangel de Lima de Paula Lisboa, advogado, inscrito na OAB/PR de n.º 105.790, todos com escritório profissional localizado na rua Doutor Leocádio, 282, Centro, Paranaguá/PR – CEP: 83.203-270, telefone: (41) 2152-2607, renunciamos todos e quaisquer poderes a nós conferidos por qualquer procuração outorgada por "},{"tipo":"campo","chave":"cliente.nome"},{"tipo":"texto","valor":", "},{"tipo":"campo","chave":"cliente.inscrito"},{"tipo":"texto","valor":" no CPF de n.º "},{"tipo":"campo","chave":"cliente.cpf"},{"tipo":"texto","valor":", para atuar em favor de seus interesses nos autos de n.º "},{"tipo":"campo","chave":"oficial.autos"},{"tipo":"texto","valor":"."}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Assim, por força do art. 112, da Lei 13.105/15"},{"tipo":"elemento","tag":"sup","itens":[{"tipo":"texto","valor":"1"}]},{"tipo":"texto","valor":" c/c art. 5º, §3º, da Lei 8.906/94"},{"tipo":"elemento","tag":"sup","itens":[{"tipo":"texto","valor":"2"}]},{"tipo":"texto","valor":", os renunciantes continuarão a representar o renunciado pelos próximos 10 dias, salvo se forem substituídos antes do término desse prazo. "}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha","modelo_condicao":"m_forma_renuncia:Com prazo de 10 dias"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"OU"}],"classe":"doc-alinhar-centro","modelo_condicao":"m_forma_renuncia:*"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Assim, por força do art. 112, da Lei 13.105/15"},{"tipo":"elemento","tag":"sup","itens":[{"tipo":"texto","valor":"3"}]},{"tipo":"texto","valor":" c/c art. 5º, §3º, da Lei 8.906/94"},{"tipo":"elemento","tag":"sup","itens":[{"tipo":"texto","valor":"4"}]},{"tipo":"texto","valor":", considerando que a parte segue representada por outro procurador, os renunciantes deixam de representá-la e de comunicá-la."}],"classe":"doc-alinhar-justificar doc-recuo-primeira-linha","modelo_condicao":"m_forma_renuncia:Com outro procurador"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"Paranaguá|PR, "},{"tipo":"campo","chave":"emissao.data"},{"tipo":"texto","valor":","}],"classe":"doc-data"},{"tipo":"elemento","tag":"hr","itens":[],"classe":"doc-nota"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"elemento","tag":"sup","itens":[{"tipo":"texto","valor":"1"}]},{"tipo":"texto","valor":" Art. 112. O advogado poderá renunciar ao mandato a qualquer tempo, provando, na forma prevista neste Código, que comunicou a renúncia ao mandante, a fim de que este nomeie sucessor."}],"classe":"doc-alinhar-justificar doc-nota","modelo_condicao":"m_forma_renuncia:Com prazo de 10 dias"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"§ 1º Durante os 10 (dez) dias seguintes, o advogado continuará a representar o mandante, desde que necessário para lhe evitar prejuízo"}],"classe":"doc-alinhar-justificar doc-nota","modelo_condicao":"m_forma_renuncia:Com prazo de 10 dias"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"§ 2º Dispensa-se a comunicação referida no caput quando a procuração tiver sido outorgada a vários advogados e a parte continuar representada por outro, apesar da renúncia."}],"classe":"doc-alinhar-justificar doc-nota","modelo_condicao":"m_forma_renuncia:Com prazo de 10 dias"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"elemento","tag":"sup","itens":[{"tipo":"texto","valor":"2"}]},{"tipo":"texto","valor":" Art. 5º O advogado postula, em juízo ou fora dele, fazendo prova do mandato."}],"classe":"doc-alinhar-justificar doc-nota","modelo_condicao":"m_forma_renuncia:Com prazo de 10 dias"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"(...)"}],"classe":"doc-alinhar-justificar doc-nota","modelo_condicao":"m_forma_renuncia:Com prazo de 10 dias"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"§ 3º O advogado que renunciar ao mandato continuará, durante os dez dias seguintes à notificação da renúncia, a representar o mandante, salvo se for substituído antes do término desse prazo."}],"classe":"doc-alinhar-justificar doc-nota","modelo_condicao":"m_forma_renuncia:Com prazo de 10 dias"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"elemento","tag":"sup","itens":[{"tipo":"texto","valor":"3"}]},{"tipo":"texto","valor":" Art. 112. O advogado poderá renunciar ao mandato a qualquer tempo, provando, na forma prevista neste Código, que comunicou a renúncia ao mandante, a fim de que este nomeie sucessor."}],"classe":"doc-alinhar-justificar doc-nota","modelo_condicao":"m_forma_renuncia:Com outro procurador"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"§ 1º Durante os 10 (dez) dias seguintes, o advogado continuará a representar o mandante, desde que necessário para lhe evitar prejuízo"}],"classe":"doc-alinhar-justificar doc-nota","modelo_condicao":"m_forma_renuncia:Com outro procurador"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"§ 2º Dispensa-se a comunicação referida no caput quando a procuração tiver sido outorgada a vários advogados e a parte continuar representada por outro, apesar da renúncia."}],"classe":"doc-alinhar-justificar doc-nota","modelo_condicao":"m_forma_renuncia:Com outro procurador"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"elemento","tag":"sup","itens":[{"tipo":"texto","valor":"4"}]},{"tipo":"texto","valor":" Art. 5º O advogado postula, em juízo ou fora dele, fazendo prova do mandato."}],"classe":"doc-alinhar-justificar doc-nota","modelo_condicao":"m_forma_renuncia:Com outro procurador"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"(...)"}],"classe":"doc-alinhar-justificar doc-nota","modelo_condicao":"m_forma_renuncia:Com outro procurador"},{"tipo":"elemento","tag":"p","itens":[{"tipo":"texto","valor":"§ 3º O advogado que renunciar ao mandato continuará, durante os dez dias seguintes à notificação da renúncia, a representar o mandante, salvo se for substituído antes do término desse prazo."}],"classe":"doc-alinhar-justificar doc-nota","modelo_condicao":"m_forma_renuncia:Com outro procurador"}],"perguntas":[{"chave":"manual.autos","rotulo":"Número dos autos","tipo":"texto","obrigatorio":false},{"chave":"manual.forma_renuncia","rotulo":"Como prossegue a representação?","tipo":"escolha","obrigatorio":true,"opcoes":["Com prazo de 10 dias","Com outro procurador"]}],"assinaturas":[]}},{"chave":"revogacao_mandato","tipo":"personalizado","categoria":"Mandato","nome":"Revogação de M