      as x(chave text, tipo text, categoria text, nome text, titulo text, fonte text, definicao jsonb)
  loop
    continue when exists (select 1 from public.modelos_documento where chave_oficial = m.chave);
    perform privado.validar_campos_modelo_documento(m.definicao, m.chave);
    insert into public.modelos_documento (chave_oficial, tipo) values (m.chave, m.tipo) returning id into v_modelo;
    insert into public.modelos_documento_versoes (modelo_id, numero, nome, titulo, categoria, definicao, fonte, publicado_em)
      values (v_modelo, 1, m.nome, m.titulo, m.categoria, m.definicao, m.fonte, now())
      returning id into v_versao;
    update public.modelos_documento set versao_atual_id = v_versao where id = v_modelo;
  end loop;
  if (select count(*) from public.modelos_documento where chave_oficial is not null and versao_atual_id is not null) < 29 then
    raise exception 'Carga dos modelos incompleta.';
  end if;
end
$carga$;
